"""Render the frozen results for biological readers; never fit or score models."""
from pathlib import Path
import hashlib, html, json
import numpy as np
import pandas as pd
import matplotlib
matplotlib.use('Agg')
import matplotlib.pyplot as plt
from drugperturb.provenance import verify_report_inputs
ROOT=Path(__file__).resolve().parents[1]
METHODS=['B0','B1','B2','M1','M2','M3']
LABELS={'B0':'Zero change','B1':'Training mean','B2':'Chemical neighbor','M1':'Fingerprint ridge','M2':'Fingerprint MLP','M3':'Molecular GNN'}
COLORS=['#94a3b8','#475569','#a78bfa','#0891b2','#f59e0b','#0f766e']
def read(name):return pd.read_csv(ROOT/name,sep='\t')
def table(frame):return frame.to_html(index=False,border=0,float_format=lambda x:f'{x:.4f}',na_rep='NA',escape=True)
def figsave(fig,path):fig.tight_layout();fig.savefig(path,dpi=160,bbox_inches='tight');plt.close(fig)
def main():
    verified_input_hashes=verify_report_inputs(ROOT)
    def digest(path):return hashlib.sha256(path.read_bytes()).hexdigest()
    out=ROOT/'reports';figdir=out/'figures';figdir.mkdir(parents=True,exist_ok=True)
    summary=json.loads((out/'final_test/summary.json').read_text());freeze=json.loads((ROOT/'receipts/dataset_freeze.json').read_text());seal=json.loads((ROOT/'receipts/prediction_seal.json').read_text())
    metrics=read('reports/final_test/metrics_by_compound.tsv');context=read('reports/final_test/compound_context.tsv');coverage=read('reports/final_test/pathway_coverage.tsv');cases=read('reports/final_test/fixed_rule_cases.tsv');qc=read('data/processed/well_qc.tsv');split=read('manifests/split_manifest.tsv')
    comparisons=json.loads((out/'final_test/paired_comparisons.json').read_text());ref=summary['simple_reference'];comparison=next(x for x in comparisons if x['method']=='M3' and x['baseline']==ref);mean_comparison=next(x for x in comparisons if x['method']=='M3' and x['baseline']=='B1')
    scores={m:summary['metrics'][m]['mean_compound_rmse'] for m in METHODS};relative=100*(scores[ref]-scores['M3'])/scores[ref]
    result=f"The molecular GNN achieved a mean compound RMSE of {scores['M3']:.3f}, compared with {scores[ref]:.3f} for the validation-selected {LABELS[ref].lower()} reference ({relative:.1f}% lower point estimate)."
    conclusion='The paired 95% structure-group interval includes zero; this experiment does not establish a reliable GNN advantage over the selected reference.' if comparison['ci_lower']<=0<=comparison['ci_upper'] else 'The paired structure-group interval excludes zero for the selected reference, conditional on this fixed split and fitted models.'
    mean_text=f"The training-mean baseline achieved {scores['B1']:.3f}. The GNN-minus-mean difference was {mean_comparison['point_estimate']:.4f} (95% interval {mean_comparison['ci_lower']:.4f} to {mean_comparison['ci_upper']:.4f}); compound-specific added value remains unestablished."
    plt.rcParams.update({'font.size':10,'axes.spines.top':False,'axes.spines.right':False,'axes.titleweight':'bold','figure.facecolor':'white'})
    fig,ax=plt.subplots(1,2,figsize=(11,4));ax[0].barh(['Source labels','Cell-qualified labels','Eligible parents','Train','Validation','Test'],[188,173,171,119,26,26],color=['#cbd5e1','#94a3b8','#0f766e','#0891b2','#f59e0b','#7c3aed']);ax[0].invert_yaxis();ax[0].set_xlabel('Number of compounds / source labels');ax[0].set_title('Distinct compound prediction units')
    ax[1].hist(qc.n_cells,bins=24,color='#0891b2',edgecolor='white');ax[1].axvline(30,color='#b91c1c',ls='--',label='Primary per-well minimum = 30');ax[1].set(xlabel='Author-QC nuclei per well',ylabel='Number of wells',title='All 392 selected wells; 36,848 nuclei');ax[1].legend(fontsize=8);figsave(fig,figdir/'01_data_quality.png')
    fig,ax=plt.subplots(1,2,figsize=(11,4));ax[0].hist(context.max_train_tanimoto,bins=np.linspace(0,1,16),color='#0891b2',edgecolor='white');ax[0].set(xlabel='Maximum training Morgan Tanimoto similarity',ylabel='Test compounds',title='Chemical support; n=26')
    gnn=metrics[metrics.method.eq('M3')].set_index('compound_id');ax[1].scatter(context.max_train_tanimoto,context.compound_id.map(gnn.rmse),c=context.response_rms,cmap='viridis',s=40);ax[1].set(xlabel='Maximum training similarity',ylabel='GNN compound RMSE',title='Errors across chemical support');figsave(fig,figdir/'02_chemical_support.png')
    fig,ax=plt.subplots(1,2,figsize=(11,4));box=ax[0].boxplot([metrics.loc[metrics.method.eq(m),'rmse'] for m in METHODS],tick_labels=METHODS,patch_artist=True)
    for patch,color in zip(box['boxes'],COLORS):patch.set_facecolor(color);patch.set_alpha(.6)
    ax[0].set(ylabel='Compound RMSE (log1p CPM delta)',title='Identical 26 held-out compounds / 2,000 genes')
    comp=[x for x in comparisons if x['method']=='M3'];points=[x['point_estimate'] for x in comp];lower=[x['point_estimate']-x['ci_lower'] for x in comp];upper=[x['ci_upper']-x['point_estimate'] for x in comp]
    ax[1].errorbar(points,range(len(comp)),xerr=[lower,upper],fmt='o',color='#0f766e',capsize=4);ax[1].axvline(0,color='#64748b',ls='--');ax[1].set_yticks(range(len(comp)),[f"M3 minus {x['baseline']}" for x in comp]);ax[1].set(xlabel='Paired RMSE difference; negative favors GNN',title='2,000 resamples of 24 structure groups');figsave(fig,figdir/'03_model_comparison.png')
    fig,ax=plt.subplots(figsize=(9,4));ax.barh(coverage.name,100*coverage.fraction_original,color='#94a3b8');ax.axvline(25,color='#b91c1c',ls='--',label='Required original-set coverage = 25%');ax.set(xlabel='Selected output genes / original set members (%)',title='Prespecified biological sets: none meets both coverage gates');ax.invert_yaxis()
    for i,row in coverage.iterrows():ax.text(100*row.fraction_original+.5,i,f'{row.selected_genes}/{row.original_members}',va='center')
    ax.set_xlim(0,40);ax.legend(fontsize=8);figsave(fig,figdir/'04_pathway_coverage.png')
    truth=np.load(ROOT/'data/processed/sealed_test_truth.npz',allow_pickle=False);pred=np.load(ROOT/'models/run_v1/test_predictions.npz',allow_pickle=False)
    expected_ids=split.loc[split.split.eq('test'),'compound_id'].tolist()
    if list(truth['ids'])!=expected_ids or list(pred['ids'])!=expected_ids:raise ValueError('Report prediction/truth identity order mismatch')
    fig,axes=plt.subplots(1,3,figsize=(12,4))
    for ax,row in zip(axes,cases.itertuples()):
        i=list(truth['ids']).index(row.compound_id);actual=truth['y'][i];prediction=pred['M3'][i];ax.scatter(actual,prediction,s=3,alpha=.18,color='#0f766e');low=min(actual.min(),prediction.min());high=max(actual.max(),prediction.max());ax.plot([low,high],[low,high],ls='--',color='#94a3b8');ax.set(xlabel='Measured gene delta',ylabel='GNN predicted delta',title=f'{row.case_rule.replace("_"," ")}\n{row.compound_id} | RMSE {row.gnn_rmse:.2f}')
    figsave(fig,figdir/'05_fixed_rule_cases.png')
    marker_section='<p>Single-cell marker summaries were not included in this execution snapshot.</p>'
    cellpath=ROOT/'data/processed/cell_state_well_summary.tsv'
    if cellpath.exists():
        cell=read('data/processed/cell_state_well_summary.tsv');mapping=read('manifests/qualified_well_mapping.tsv');mapping=mapping[mapping.eligible]
        marker=[]
        for sid,g in cell.groupby('set_id'):
            med=g.set_index('Combo')['median']
            for row in mapping.itertuples():marker.append(dict(compound_id=row.treatment,replicate=row.replicate,set_id=sid,delta_well_median=float(med[row.Combo]-med[row.control_Combo])))
        marker=pd.DataFrame(marker);marker.to_csv(out/'cell_state_contrasts.tsv',sep='\t',index=False)
        fig,axes=plt.subplots(1,2,figsize=(10,4))
        for ax,(sid,g) in zip(axes,marker.groupby('set_id')):
            wide=g.pivot(index='compound_id',columns='replicate',values='delta_well_median');ax.scatter(wide.rep1,wide.rep2,s=12,alpha=.6,color='#0f766e');ax.axhline(0,color='#cbd5e1');ax.axvline(0,color='#cbd5e1');ax.set(xlabel='Replicate 1: treated median minus vehicle median',ylabel='Replicate 2: treated median minus vehicle median',title=f'{sid}; {len(wide)} compounds')
        figsave(fig,figdir/'06_cell_state_replicates.png');marker_section='<p>Scores use all fixed 43 S and 54 G2/M marker genes at single-cell resolution, independently of model output selection. Each cell is normalized by total human UMI. The paired plots describe marker-expression shifts across two experiments; they are not phase assignments or evidence of causal pathway activity.</p><img src="figures/06_cell_state_replicates.png">'
    display=pd.DataFrame([{'Method':m,'Description':LABELS[m],'Mean compound RMSE':scores[m],'Mean gene-rank correlation':summary['metrics'][m]['mean_spearman'],'Undefined rank correlations':summary['metrics'][m]['n_spearman_undefined']} for m in METHODS])
    diagpath=ROOT/'receipts/development_diagnostics.tsv';diag_section=table(pd.read_csv(diagpath,sep='\t')[['diagnostic','run','method','n_train_compounds','n_evaluation_compounds','mean_compound_RMSE']]) if diagpath.exists() else '<p>Development diagnostics are not included in this execution snapshot.</p>'
    senspath=out/'sensitivity/metrics_summary.tsv';sens_section=table(pd.read_csv(senspath,sep='\t').pivot_table(index=['scenario','n_compounds'],columns='method',values='mean_compound_rmse').reset_index()) if senspath.exists() else '<p>Control and cell-count sensitivity results are not included in this execution snapshot.</p>'
    css='body{font:16px/1.6 system-ui,sans-serif;color:#183044;background:#f4f7f8;margin:0}main{max-width:1120px;margin:auto;padding:40px;background:white}h1{font-size:40px;line-height:1.15}h2{margin-top:42px;color:#0f766e}p{max-width:95ch}.eyebrow{color:#0f766e;font-weight:700;letter-spacing:.12em}table{border-collapse:collapse;width:100%;font-size:13px;display:block;overflow-x:auto}td,th{padding:9px;border-bottom:1px solid #dbe4e8;text-align:left}th{background:#ecf4f2}img{width:100%;height:auto;margin:20px 0}.callout{padding:20px;background:#eef6f4;border-left:4px solid #0f766e}.muted{color:#526471;font-size:14px}a{color:#087f8c}code{font-size:13px} @media print{body,main{background:white;padding:0}.page{break-after:page}h2{break-after:avoid}img,table{break-inside:avoid}}'
    body=f'''<p class="eyebrow">DRUGPERTURB · FROZEN BENCHMARK v1</p><h1>Can chemical structure predict transcriptional change?</h1><p>A public-data study of A549 cells exposed for 24 hours at 1 µM, comparing simple references with fingerprint and molecular-graph models.</p><div class="callout"><b>{html.escape(result)}</b><p>{html.escape(conclusion)}</p><p>{html.escape(mean_text)}</p></div>
<h2>1. Data and experimental units</h2><p>188 source treatment labels were evaluated. 173 met the two-replicate cell-count rule; chemical qualification and duplicate-parent handling left 171 distinct standardized parent compounds. These contributed 33,055 treatment nuclei and 886 nuclei in eight unique matched vehicle wells. The broader QC extract contains 36,848 nuclei across 392 wells, including excluded treatments and additional vehicle wells. Cells improve response measurement; they are not additional independent drugs.</p><p>The frozen split contains 119 training, 26 validation and 26 test compounds. The test comprises 22 ring-scaffold groups and two acyclic parent groups. No canonical parent or defined structure group crosses a split.</p><img src="figures/01_data_quality.png">
<h2>2. Prediction task and chemical support</h2><p>For each well, raw human-gene UMI counts were summed, scaled to counts per million, and log1p transformed. The response is treated minus its exact plate, replicate and dose-pattern vehicle; the two replicate differences receive equal weight. Input features contain chemical structure only. Author embeddings, global size factors and measured treated-cell expression are never model inputs.</p><p>Only the training compounds selected the 2,000 most variable genes, standardization and 20 target principal components. The retained components explain {freeze['training_PCA_explained_variance_fraction']:.1%} of standardized training variance. Predictions return to the actual selected-gene scale for every validation and test score; measured truth is never PCA-smoothed. The absence of a low-expression filter and the small compound sample can favor noisy variable genes and limit biological coverage.</p><img src="figures/02_chemical_support.png">
<h2>3. Model comparison</h2>{table(display)}<p>RMSE measures error in the size of expression change; lower is better. Each drug first receives its own RMSE across 2,000 genes, then drugs are weighted equally. Spearman measures gene-change ranking, not amplitude. The zero-response baseline has undefined ranking correlation for all 26 drugs and is retained as NA.</p><p>Ridge used four fixed penalties. Each neural model used four fixed configurations and three seeds; checkpoint selection used actual validation gene-space error. The chosen candidate averages three seed predictions, with all individual seed results retained. GNN has two bond-aware message-passing layers with mean neighborhood and molecular pooling. No pretrained model or external training data were used.</p><img src="figures/03_model_comparison.png"><p>GNN minus {ref}: {comparison['point_estimate']:.4f}, 95% interval [{comparison['ci_lower']:.4f}, {comparison['ci_upper']:.4f}]. Intervals resample 24 structure groups 2,000 times, retaining all compounds within sampled groups. They are conditional on this split and fitted models; shared controls, plate effects, retraining and external-study variation are not fully covered. Three random seeds are computational repeats, not new biological samples.</p>
<h2>4. Biological interpretation and coverage</h2><p>Cell-cycle markers and Reactome 97 acetylation, deacetylation and stress sets were frozen before evaluation. Exact symbols were mapped first, followed by official HGNC mappings to the original gene annotation. A quantitative pathway comparison requires at least 10 selected genes and at least 25% of original members. None of the five sets passed both gates. Pathway recovery is therefore not evaluated; missing coverage is not repaired after inspecting test results.</p>{table(coverage[['name','original_members','mapped_unique_genes','selected_genes','fraction_original','quantitatively_evaluable']])}<img src="figures/04_pathway_coverage.png">{marker_section}
<h2>5. Error cases and experimental reliability</h2><p>Three cases follow fixed rules: highest GNN error, lowest measured response magnitude, and lowest similarity to training chemicals, with distinct compounds. Every scatter includes all 2,000 output genes. These cases illustrate error patterns; they did not change the model or test protocol.</p>{table(cases[['case_rule','compound_id','name','rep1_cells','rep2_cells','max_train_tanimoto','replicate_rmse','gnn_rmse']])}<img src="figures/05_fixed_rule_cases.png"><p>Across the26 test compounds, median replicate Spearman is {context.replicate_spearman.median():.3f} and median replicate RMSE is {context.replicate_rmse.median():.3f}. Two-replicate disagreement combines measurement noise and experimental variation; it is not a precise estimate of irreducible error. Low cell yield is not automatically evidence of toxicity. Per-replicate and plate-level errors are available in the downloadable tables.</p>
<h2>6. Development diagnostics</h2><p>Three compound-level folds and nested 25%, 50%, 100% learning subsets use only the original development data. Each fits preprocessing again. GNN uses the selected settings and a fixed epoch budget derived from validation; no evaluation-fold label controls training. GNN had higher error than Ridge in all three exploratory compound folds. These comparisons can use different gene sets and compound compositions, so a score difference cannot be attributed solely to chemical novelty or training size. This is a single-seed diagnostic, not a replacement for the primary frozen test.</p>{diag_section}
<h2>7. Sensitivity analyses</h2><p>Frozen predictions are compared with an alternative same-plate vehicle definition and with the subset passing a 50-cell threshold. On the same 26 test compounds, the alternative two-vehicle definition changed point-estimate rankings: zero-change RMSE 1.0131, training mean 1.0150, Ridge 1.0368 and GNN 1.0395. Lower absolute errors here reflect changed reference responses, not better models. The result is sensitive to the control definition. The 50-cell check retains 24 of26 compounds. These checks alter the reference or evaluated subset; they are not independently retrained benchmarks or external validation.</p>{sens_section}
<h2>8. What the study supports</h2><table><tr><th>Testable hypothesis</th><th>Observed evidence</th><th>Alternative explanation</th><th>Still required</th></tr><tr><td>Structure helps predict drug-specific responses</td><td>GNN has a slightly lower point error than the mean baseline</td><td>Intervals overlap zero; shared control/plate effects, average responses and experimental noise may contribute</td><td>Prespecified independent perturbation dataset and stronger compound coverage</td></tr><tr><td>Epigenetic mechanisms are recovered</td><td>Fixed pathways have insufficient output coverage</td><td>Training variance selection emphasizes other/noisy genes</td><td>A new protocol with training-defined expression filtering and adequate pathway coverage, evaluated on fresh heldout data</td></tr><tr><td>Predictions transfer across biological contexts</td><td>Only A549/24h/1µM was studied</td><td>Cell-state and dose dependence are untested</td><td>Separate public dose/cell-line datasets; no private or wet-lab inputs are assumed</td></tr></table><p>This model does not establish drug efficacy, target engagement, toxicity, clinical benefit or antibody-binding/design performance. Its drug-discovery contribution is an auditable molecular-learning and perturbation-response evaluation workflow.</p>
<h2>9. Reproducibility and sources</h2><p>Real main training ran on the primary CPU host in approximately {seal['elapsed_seconds']/60:.1f} minutes. Source revision: <code>{seal['source_commit']}</code>. Inputs, split, selected genes, model weights, configuration, trajectories and predictions have SHA256 receipts. Final evaluation verifies the prediction seal before loading test truth. No paid AWS execution or independent external dataset is claimed. Subsequent verification established identical predictions in two fresh runs on one fixed host/container and consistent Docker inference from the saved primary weights. Cross-host GNN retraining failed the prespecified numerical tolerance; see the separate <a href="../docs/EXECUTION_EVIDENCE.md">execution evidence</a>. These checks do not replace the primary scientific results.</p><p><a href="../manifests/source_manifest.tsv">Source manifest</a> · <a href="../manifests/split_manifest.tsv">Frozen split</a> · <a href="final_test/metrics_by_compound.tsv">All compound metrics</a> · <a href="final_test/paired_comparisons.json">Paired intervals</a> · <a href="../receipts/training_runs.tsv">Every training run</a> · <a href="../docs/REPRODUCIBILITY.md">Reproduction instructions</a></p><p>Public sources: <a href="https://www.ncbi.nlm.nih.gov/geo/query/acc.cgi?acc=GSE139944">GEO GSE139944</a>; <a href="https://pmc.ncbi.nlm.nih.gov/articles/PMC7289078/">Srivatsan et al., Science 2020</a>; <a href="https://github.com/cole-trapnell-lab/sci-plex/tree/079639c50811dd43a206a779ab2f0199a147c98f">Pinned author preprocessing</a>; <a href="https://download.reactome.org/97/">Reactome 97</a>; <a href="https://www.genenames.org/">HGNC</a>. Public download availability does not imply that the project code license applies to third-party source data.</p>'''
    (out/'report.html').write_text(f'<!doctype html><html lang="en"><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1"><title>DrugPerturb | Results and methods</title><style>{css}</style><main>{body}</main></html>')
    short=f'''<section class="page"><p class="eyebrow">DRUGPERTURB · BIOLOGICAL SUMMARY · 1/2</p><h1>Chemical structure to transcriptional response</h1><p>Public sci-Plex3 data · A549 · 24 hours · 1 µM</p><h2>Question</h2><p>Can a small molecular graph model predict the expression changes caused by compounds whose structural groups were absent from training?</p><h2>Evidence</h2><p>171 distinct standardized parent compounds; 119 training / 26 validation / 26 final test. Two biological experiment replicates per compound. Training-only selection of 2,000 genes; six methods evaluated against identical measured changes.</p><div class="callout">{html.escape(result)}<p>{html.escape(conclusion)}</p></div>{table(display[['Method','Description','Mean compound RMSE']])}<p>{html.escape(mean_text)}</p></section><section><p class="eyebrow">BIOLOGICAL SUMMARY · 2/2</p><h2>What the biology says</h2><p>No prespecified gene set met the frozen coverage rule, so the study makes no claim of pathway recovery. Single-cell S and G2/M marker summaries provide experimental context independently of model outputs.</p><h2>Why confidence is limited</h2><p>Using two same-plate vehicle wells changes the point-estimate ranking: zero-change and training-mean references outperform the GNN under that response definition. GNN also has higher error than Ridge in all three exploratory development folds.</p><p>Only 26 drugs form the final test. The 24 structure groups include two acyclic parent groups. Shared vehicles and two experimental replicates limit independence. The model is restricted to one cell line, time and dose; there is no external dataset validation.</p><h2>Practical interpretation</h2><p>The study establishes a reproducible model-training and evaluation implementation. It does not yet establish that chemical structure predicts drug-specific response better than a strong mean-response baseline. The inconclusive added-value result is retained with all drug errors, seeds and training records.</p><h2>Next scientific test</h2><p>Define a new protocol using training-only expression-quality filtering and adequate fixed pathway coverage; evaluate it against untouched public data. The v1 test set is already used and must not become a tuning set disguised as new validation.</p><p>Full methods, figures and tables: <a href="report.html">report.html</a>. AWS execution, therapeutic efficacy and antibody discovery are not demonstrated.</p></section>'''
    (out/'biologist_summary.html').write_text(f'<!doctype html><html lang="en"><meta charset="utf-8"><title>DrugPerturb | Two-page biological summary</title><style>{css}main{{max-width:850px}}@page{{size:A4;margin:16mm}}@media print{{body{{font-size:11pt}}h1{{font-size:26pt}}h2{{margin-top:18px}}td,th{{padding:5px}}}}</style><main>{short}</main></html>')
    report_files=[out/'report.html',out/'biologist_summary.html',*figdir.glob('*.png')]
    if (out/'cell_state_contrasts.tsv').exists():report_files.append(out/'cell_state_contrasts.tsv')
    input_files=[ROOT/'receipts/final_evaluation.json',ROOT/'receipts/prediction_seal.json',ROOT/'receipts/dataset_freeze.json',Path(__file__),ROOT/'data/processed/well_qc.tsv',ROOT/'manifests/qualified_well_mapping.tsv',*list((out/'final_test').glob('*'))]
    input_files += [f for f in [cellpath,diagpath,senspath,ROOT/'receipts/development_diagnostics.json',ROOT/'receipts/sensitivity.json'] if f.exists()]
    (ROOT/'receipts/report_artifacts.json').write_text(json.dumps({'scope':'Presentation of frozen results; no model changes','input_hashes':{**verified_input_hashes,**{str(f.relative_to(ROOT)):digest(f) for f in input_files}},'files':{str(f.relative_to(ROOT)):hashlib.sha256(f.read_bytes()).hexdigest() for f in report_files}},indent=2)+'\n')
    print('Rendered report, two-page summary and',len(list(figdir.glob('*.png'))),'figures.')
if __name__=='__main__':main()
